(()=>{const app=document.querySelector('#gate6'),K='rules-city-gate6-v1',publicStages=['c2','q2','l2','a2','boss','by','bc','b1','ba','b2','bb','b3'],courtStages=['c4a','c4b','q4','q5','l4','a4'];let S=JSON.parse(localStorage.getItem(K)||'{"s":"intro","t":{},"r":{},"complete":false}');if(location.pathname.endsWith('/index.html')||location.pathname==='/'){S={...S,s:'intro',t:{},r:{}};localStorage.setItem(K,JSON.stringify(S))}const save=()=>localStorage.setItem(K,JSON.stringify(S)),sh=a=>[...a].sort(()=>Math.random()-.5),go=s=>{S.s=s;save();render()},btn=(x,s,c='')=>`<button class="button ${c}" data-go="${s}">${x}</button>`,frame=x=>{app.className=(S.s==='complete'?'complete ':'')+(publicStages.includes(S.s)?'public ':courtStages.includes(S.s)?'court ':'');app.innerHTML=`<div class="shade"></div><header class="hud"><span>規則之城｜GATE 6</span><button data-go="start">回到本關開頭</button></header><section class="scene">${x}</section>`;bind()};
const Q={q1:['阿哲可以直接聲請裁判憲法審查嗎？',['可以，因為判決已經確定','可以，因為主張基本權受侵害','不可以，因為尚未用盡審級救濟','不可以，因為人民不得提出聲請'],2,'再看看程序紀錄：他是不是還有可以使用的上訴方式？','他仍可依法上訴，卻沒有提起。'],q2:['怡君主要質疑的是什麼？',['裁罰承辦人','審理案件的法官','裁判所適用的法規範','市政府交通政策'],2,'她質疑的是「法官判錯」，還是「那一條規定本身可能有問題」？','她認為一律許可的規定本身可能限制過廣。'],q3:['子翔這次真正提出的憲法問題是什麼？',['法律本身禁止新聞報導','政府公開資料內容錯誤','法院裁判是否充分保障言論與新聞自由','食品公司不應提出民事訴訟'],2,'他沒有主張法律本身不能存在；再看看他真正不滿的是法院「怎麼判」。','他質疑法院在個案中是否充分衡量言論與新聞自由。'],q4:['現在對法規範產生違憲疑義的是誰？',['本案當事人','原處分機關','審理案件的法院','立法委員'],2,'注意正在翻閱法規彙編、必須以此作出判決的人。','是審理案件的法院發現適用法律可能有違憲疑義。'],q5:['法院現在質疑的是什麼？',['當事人的證詞','本案應適用的法規範','行政機關態度','其他法院裁判'],1,'法官必須適用哪一個規定，才是本案的關鍵？','法院質疑的是必須適用的法規範。'],q6:['小豪真正希望憲法法庭做什麼？',['審查法律是否違憲','審查基本權限制','重新認定事實與判斷證據','審查行政命令'],2,'他現在要求的是重新判斷證據，還是指出裁判本身的憲法問題？','他要求重看影像與證人說詞，是重新認定事實與證據。'],b1:['主張甲主要質疑什麼？',['行政人員','法規範','確定終局裁判','救濟程序'],1,'主張甲問的是「這條規定本身」是否限制太廣。','主張甲指向規定本身。'],b2:['主張乙主要質疑什麼？',['法規範','行政處分','確定終局裁判','行政機關首長'],2,'主張乙指向法院已經作成的判斷。','主張乙指向確定終局裁判。'],b3:['同一個人民聲請案件，是否可能同時涉及法規範與確定終局裁判？',['不可能，只能選一種','不可能，人民只能聲請裁判審查','可能，須分別判斷其審查對象','可能，但只有法院可以提出'],2,'請分別看每一個主張在質疑什麼，而不是只看聲請人身分。','同一案件可分別指向不同審查對象。']};
Object.assign(Q,{q3:['子翔真正提出的憲法問題是什麼？',['食品公司根本不能提出訴訟','主管機關的公開資料一定錯誤','法院的裁判是否過度限制言論與新聞自由','所有公共議題報導都不能負法律責任'],2,'他沒有主張法律本身不能存在；再看看他真正不滿的是法院「怎麼判」。','他質疑法院對合理查證的要求，是否過度限制新聞自由。'],q3b:['那裁判憲法審查真正要看的，是什麼？',['哪個證人的說法比較可信','原法院是不是應該判另一方贏','確定終局裁判是否侵害憲法保障的權利','所有案件證據是否重新調查'],2,'不是重新判斷證據或輸贏；要看裁判本身是否有憲法問題。','裁判憲法審查檢驗確定終局裁判是否侵害憲法保障權利。'],q6b:['哪一個才是在提出「裁判的憲法問題」？',['「監視器裡的人不是我，請再看一次。」','「證人在說謊，請重新判斷他的證詞。」','「確定終局裁判對我的基本權限制，是否符合憲法要求？」','「原法官判錯了，請換一位法官重新判。」'],2,'請找出直接指出裁判憲法問題、而非要求重看證據的主張。','這一項直接指出確定終局裁判可能不符合憲法要求。']});
function quiz(id,n){let q=Q[id];frame(`<div class="paper"><div class="tag">判斷紀錄</div><h2>${q[0]}</h2>${sh(q[1].map((x,i)=>[x,i])).map(([x,i],p)=>`<button class="answer" data-a="${id}|${i}|${n}"><b>${'ABCD'[p]}</b>${x}</button>`).join('')}<div class="feedback"></div></div>`)}
function retry(id,n){let q=Q[id];frame(`<div class="paper"><h2>${q[0]}</h2><div class="hint">提示：${q[3]}</div>${btn('再試一次',`q:${id}:${n}`,'primary')}</div>`)}
function bins(n,right,hint){app.querySelectorAll('[data-bin]').forEach(b=>b.onclick=()=>b.dataset.bin===right?go(n):$('.feedback').innerHTML=`<div class="hint">${hint}</div>`)}
function lawbin(n){frame(`<div class="caption">請將卷宗送入正確案件匣。</div><div class="paper"><div class="bins"><button class="folder" data-bin="yes">法規範<br>憲法審查</button><button class="folder" data-bin="no">裁判<br>憲法審查</button></div><div class="feedback"></div></div>`);bins(n,'yes','再看一次：問題在規定本身，還是法院怎麼判？')}
function yn(title,yes,n,hint){frame(`<div class="paper"><h2>${title}</h2><button class="answer" data-yn="1"><b>是</b></button><button class="answer" data-yn="0"><b>不是</b></button><div class="feedback"></div></div>`);app.querySelectorAll('[data-yn]').forEach(b=>b.onclick=()=>b.dataset.yn===yes?go(n):$('.feedback').innerHTML=`<div class="hint">${hint}</div>`)}
function $(s){return document.querySelector(s)}
function render(){if(S.s.startsWith('retry-')){let[,id,n]=S.s.split('-');return retry(id,n)}switch(S.s){
case'intro':frame(`<div class="caption">法律可以規範人民。<br><br>但如果——<br><b>法律本身出了問題呢？</b><br><br>如果法院已經作成判決，<br><b>判決本身也可能違反憲法嗎？</b></div><div class="paper"><div class="tag">GATE 6｜最後審查室</div><h1>當法律與裁判都可能違憲</h1>${btn('進入案件受理室','docs','primary')}</div>`);break;
case'docs':{let a=S.r.a,b=S.r.b;frame(`<div class="caption"><b>案件一｜網路發文爭議</b><br>阿哲公開批評同學，被判賠償新臺幣 6 萬元。</div><div class="paper"><p>「我只是發表自己的意見。法院這樣判，不是侵害我的言論自由嗎？」</p><div class="docs"><button class="doc ${a?'read':''}" data-doc="a"><b>第一審判決書</b><small>${a?'已閱':'點閱最後一行'}</small></button><button class="doc ${b?'read':''}" data-doc="b"><b>訴訟紀錄</b><small>${b?'已閱':'點閱上訴紀錄'}</small></button></div>${a&&b?btn('進行判斷','q1','primary'):'<small>兩份資料都看完後，才能繼續。</small>'}</div>`);break}
case'q1':quiz('q1','r1');break;case'r1':frame(`<div class="paper"><div class="flow">第一審敗訴<br>↓<br><b>依法可以上訴</b><br>↓<br>沒有上訴<br>↓<br>判決確定</div><div class="stamp">尚未用盡審級救濟</div><p>「判決確定」不一定等於「用盡審級救濟」。</p>${btn('下一案件','c2','primary')}</div>`);break;
case'c2':frame(`<div class="caption"><b>案件二｜市政府廣場</b><br>怡君發放「改善行人安全」傳單，因未先申請許可而受裁罰。</div><div class="paper"><div class="flow">裁罰 ↓ 行政救濟 ↓ 行政訴訟 ↓ 依法走完審級 ↓ <b>不利確定終局裁判</b></div><div class="note">「為什麼所有人在這裡發傳單，不分情況，都一定要先取得許可？」</div>${btn('查看主要質疑','q2','primary')}</div>`);break;case'q2':quiz('q2','l2');break;case'l2':lawbin('a2');break;case'a2':frame(`<div class="paper"><div class="hint">聲請人雖然是人民，但她質疑的是「法規範」。</div><h2>人民 ≠ 一定是裁判憲法審查</h2>${btn('下一案件','c3a','primary')}</div>`);break;
case'c3a':frame(`<div class="caption"><b>案件三｜食品標示報導</b><br>記者子翔接獲消費者投訴，質疑產品標示可能使人誤解。</div><div class="paper"><div class="case-note">他查閱主管機關過去公開的稽查資料、訪問數名消費者，也查閱公司公開說明。</div><div class="case-note">資料實際記載：<br><b>曾要求業者改善產品標示方式。</b></div><div class="case-note">但子翔報導標題寫成：<br><b>「食品公司產品標示遭認定違法」</b></div><p>公司刊登前曾完整說明：只是要求改善，未正式認定違法；但文章只呈現部分回應。</p>${btn('查看法院判決理由','c3b','primary')}</div>`);break;
case'c3b':frame(`<div class="caption"><b>案件三｜實體判決書</b></div><div class="paper"><div class="docview"><b>法院認為：</b><ol><li>本案報導涉及公共議題。</li><li>記者確實曾進行部分查證。</li><li>但「要求改善」與「認定違法」並不相同。</li><li>公司在報導前也曾提出說明。</li><li>因此，對關鍵事實的查證與呈現仍有不足。</li></ol></div><p><b>最後判決：子翔應負損害賠償責任。</b></p><p>子翔依法走完可使用的審級救濟，取得不利確定終局裁判。</p><div class="note">「我不是認為相關法律不能存在。我認為法院對『合理查證』要求得太高，沒有充分考量公共議題，因而過度限制我的言論與新聞自由。」</div>${btn('判斷他提出的憲法問題','q3','primary')}</div>`);break;case'q3':quiz('q3','c3c');break;case'c3c':yn('憲法法庭是要重新判一次誰輸誰贏嗎？','0','q3b','它不是重判勝敗，而是檢驗裁判是否有憲法問題。');break;case'q3b':quiz('q3b','c4a');break;
case'c4a':frame(`<div class="caption"><b>案件四｜五年不能開車？</b><br>阿凱靠載客維生，是一名職業駕駛。</div><div class="paper"><p>某次他違反營業管理規定，遭主管機關裁罰，且已繳清罰鍰。</p><p>幾個月後，他準備重新申請職業駕駛資格，卻收到通知：</p><div class="docview"><b>曾因該類違規受行政處分者，五年內不得從事此項駕駛工作。</b></div><div class="note">「罰款我已經繳了。就因為那一次違規，我五年都不能靠這個工作？」</div><small>本案例為教學模擬情境。</small>${btn('進入普通法院審判庭','c4b','primary')}</div>`);break;
case'c4b':frame(`<div class="caption"><b>案件四｜審判席上的法規彙編</b></div><div class="paper"><div class="docview">「本案要作成判決，必須適用這一條法律。」<br><br>「但不分違規情節輕重，一律限制五年……」<br><br><b>「這會不會過度限制人民的工作權？」</b></div>${btn('進入判斷','q4','primary')}</div>`);break;case'q4':quiz('q4','q5');break;case'q5':quiz('q5','l4');break;case'l4':lawbin('a4');break;case'a4':frame(`<div class="paper"><h2>法規範憲法審查</h2><div class="hint">法院也可能聲請法規範憲法審查。先看他在質疑什麼。</div>${btn('下一案件','c5','primary')}</div>`);break;
case'c5':frame(`<div class="caption"><b>案件五｜夜間街道監視器</b><br>小豪一路上訴後敗訴，取得確定終局裁判。</div><div class="paper"><div class="note">「監視器那麼模糊，那個人根本不是我！那個證人也在說謊！請憲法法庭重新看一次證據！」</div>${btn('判斷他的要求','q6','primary')}</div>`);break;case'q6':quiz('q6','nf');break;case'nf':yn('這是裁判憲法審查的功能嗎？','0','boss','他現在要求的是重新認定事實與判斷證據。');break;
case'boss':frame(`<div class="caption"><b>最終案件｜禁拍令</b><br>雨婷在政府機關大廳記錄陳情，沒有阻擋動線或干擾公務，卻因攝影遭裁罰。</div><div class="paper"><div class="flow">裁罰 ↓ 行政救濟 ↓ 行政訴訟 ↓ 依法提起可使用的上訴 ↓ <b>不利確定終局裁判</b></div>${btn('檢查救濟資格','by','primary')}</div>`);break;case'by':yn('雨婷是否已經用盡依法可使用的審級救濟？','1','bc','流程顯示她已依法提起可使用的上訴。');break;case'bc':frame(`<div class="paper"><div class="tag">雨婷的聲請書</div><div class="note"><b>主張甲</b><br>這條規定不管有沒有妨礙公務，都一律禁止拍攝。這條規定本身是不是限制得太廣？</div>${btn('判斷主張甲','b1','primary')}</div>`);break;case'b1':quiz('b1','ba');break;case'ba':frame(`<div class="paper"><h2>→ 法規範憲法審查</h2><div class="note"><b>主張乙</b><br>法院認為只要進入政府機關，就幾乎不能主張攝影與表意自由。這個確定終局裁判本身，有沒有憲法上的問題？</div>${btn('判斷主張乙','b2','primary')}</div>`);break;case'b2':quiz('b2','bb');break;case'bb':frame(`<div class="paper"><h2>→ 裁判憲法審查</h2>${btn('完成最後判斷','b3','primary')}</div>`);break;case'b3':quiz('b3','notes');break;
case'notes':frame(`<div class="complete-card"><div class="tag">憲法法庭受理筆記</div><div class="notebook"><h2>人民聲請前</h2>基本權可能受到侵害<br>↓<br>依法提起救濟<br>↓<br><b>用盡審級救濟</b><br>↓<br><b>不利確定終局裁判</b><p class="pencil">判決確定 ≠ 一定用盡救濟</p><hr><h2>兩種審查</h2><b>法規範憲法審查</b><br>問題在法律、命令等法規範本身。<br>例：規定是否過度限制基本權？<br><span class="small">人民、法院等依法得聲請者。</span><br><br><b>裁判憲法審查</b><br>問題在不利確定終局裁判本身。<br>例：法院裁判是否侵害憲法保障權利？<hr><div class="sticky">① 人民 ≠ 一定是裁判憲法審查<br>② 法院也可能聲請法規範憲法審查<br>③ 憲法法庭 ≠ 第四審</div><p class="pencil">不是重新認定事實、重看證據或再判一次誰輸誰贏。</p><b>誰來聲請？ → 救濟走完了嗎？ → 他在質疑什麼？</b><br>法規範 → 法規範憲法審查<br>確定終局裁判 → 裁判憲法審查</div>${btn('完成案件整理','complete','primary')}</div>`);break;
case'complete':S.complete=true;save();frame(`<div class="paper"><h1>GATE 6 COMPLETE</h1><p>最後審查室的卷宗已整理完成。</p>${btn('重新挑戰本關','restart','primary')}${btn('回到本關開頭','start','red')}</div>`);break;default:S.s='intro';save();render()}}
function bind(){app.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{let s=b.dataset.go;if(s==='start'){S.s='intro';save();render()}else if(s==='restart'){S={s:'intro',t:{},r:{},complete:S.complete};save();render()}else if(s.startsWith('q:')){let[,id,n]=s.split(':');quiz(id,n)}else if(s==='show-answer'){S.s='answer-reveal';save();render()}else go(s)});app.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{let[id,x,n]=b.dataset.a.split('|'),q=Q[id],t=S.t[id]||0;if(+x===q[2])go(n);else if(!t){S.t[id]=1;S.s=`retry-${id}-${n}`;save();render()}else{S.t[id]=2;S.wrong={id,x:+x,n};S.s='second-wrong';save();render()}});app.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>{let x=b.dataset.doc;S.r[x]=true;save();b.disabled=true;b.insertAdjacentHTML('afterend',`<div class="docview">${x==='a'?'如不服本判決，得於法定期間內提起上訴。':'上訴紀錄：無；上訴期間：已屆滿。'}<br>${btn('返回卷宗','docs')}</div>`);b.nextElementSibling.querySelector('[data-go]').onclick=()=>go('docs')})}
const renderBase=render;render=function(){if(S.s==='c5'){frame(`<div class="paper"><h2>案件五｜退件辨認</h2><div class="note">小豪：「監視器裡的人不是我！證人在說謊！請憲法法庭重新看證據！」</div>${btn('判斷他的要求','q6','primary')}</div>`);return}if(S.s==='nf'){yn('這是裁判憲法審查的功能嗎？','0','q6b','他現在要求的是重新認定事實與判斷證據。');return}if(S.s==='q6b'){quiz('q6b','c5compare');return}if(S.s==='c5compare'){frame(`<div class="paper"><div class="docs"><div class="doc"><b>一般審判爭議</b><small>證人說謊／監視器看錯／證據判斷錯誤</small><div class="stamp">重新認定事實／證據</div></div><div class="doc"><b>憲法問題</b><small>確定終局裁判是否侵害憲法保障權利？</small><div class="stamp">裁判憲法審查</div></div></div><h2>官司判錯了 ≠ 裁判違憲</h2>${btn('繼續','c5trap','primary')}</div>`);return}if(S.s==='c5trap'){yn('只要在聲請書寫「我的基本權受到侵害」，就一定可以嗎？','0','boss','必須具體指出哪項憲法上權利受侵害，以及裁判為何產生憲法問題。');return}if(S.s==='boss'){frame(`<div class="paper"><h2>最終案件｜禁拍令</h2><div class="note">雨婷正在拍攝民眾陳情，沒有阻擋動線、沒有進入限制區，也沒有干擾公務。<br><br>工作人員：「小姐，這裡不能拍攝。」<br>雨婷：「我沒有影響辦公，也沒有進入限制區。」</div><div class="docview"><b>未經許可禁止攝影／錄音</b><br>任何人在政府機關辦公場所內，未經機關首長同意，不得攝影或錄音。</div>${btn('查看後續救濟流程','bossflow','primary')}</div>`);app.classList.add('boss-scene');return}if(S.s==='bossflow'){frame(`<div class="paper"><div class="flow">裁罰 ↓ 行政救濟 ↓ 行政訴訟 ↓ 依法提起可使用的上訴 ↓ <b>不利確定終局裁判</b></div>${btn('檢查救濟資格','by','primary')}</div>`);app.classList.add('boss-scene');return}if(S.s==='bc'){frame(`<div class="paper"><h2>主張甲｜這條規定本身，限制得太廣嗎？</h2><div class="note">「這條規定不管有沒有妨礙公務，都一律要求先取得許可。我認為問題可能出在這條規定本身。」</div>${btn('判斷主張甲','b1','primary')}</div>`);app.classList.add('boss-scene');return}if(S.s==='ba'){frame(`<div class="paper"><h2>→ 法規範憲法審查</h2><div class="note"><b>主張乙｜法院最後這樣判，有沒有憲法問題？</b><br>「法院最後判我敗訴。只要進入政府機關，原則上就很難主張攝影與表意自由；我認為這個判決本身過度限制了我的言論與表意自由。」</div>${btn('判斷主張乙','b2','primary')}</div>`);app.classList.add('boss-scene');return}if(S.s==='bb'){frame(`<div class="paper"><h2>→ 裁判憲法審查</h2><p>她這次不是在說規定本身有問題，而是在主張法院最後這樣判，可能侵害她的憲法權利。</p><div class="docs"><div class="doc"><b>主張甲</b><small>禁拍規定本身限制過廣</small><b>→ 法規範憲法審查</b></div><div class="doc"><b>主張乙</b><small>確定終局裁判過度限制基本權</small><b>→ 裁判憲法審查</b></div></div>${btn('完成最後判斷','b3','primary')}</div>`);app.classList.add('boss-scene');return}return renderBase()};render()})();
